scripts.雪莲姥姥对话.txt:
//	和雪莲姥姥对话

	Say("雪莲姥姥：在我后悔以前，你走吧——", 75);
	Return;

scripts.雪莲姥姥死亡.txt:
// 雪莲姥姥被击败

	FadeOut();
	StopMusic();
	PlayMusic("夜色.mp3");
	ClearBody();
	DelNpc("雪莲姥姥");
	AddNpc("npc047_雪莲姥姥.ini", 15, 20, 1);
	SaveNpc();
	SaveObj();
	SetPlayerPos(14, 21);
	SetPlayerDir(5);
	ClearEffect();
	FadeIn();
	
	Say("雪莲姥姥：哈哈哈哈，姥姥很久没有舒活舒活筋骨了！", 75);
	Say("张琳心：……多谢姥姥成全！", 101);
	Say("雪莲姥姥：娃娃，姥姥且问你，你这样拼死拼活为了那个——独孤小子，他可是你的心上人？", 75);
	Say("张琳心：……姥姥，如果他死了，我……我也不能活了！", 104);
	Say("雪莲姥姥：哈哈哈哈！——唉！……薄幸人，这下你又满意了！世上又多了一个可怜的女人，老天，你太不公平啊……", 75);
	NpcGoto("雪莲姥姥", 16, 16);
	SetNpcDir("雪莲姥姥", 5);
	PlayerGoto(15, 19);
	SetPlayerDir(5);
	Say("张琳心：前辈！", 105);
	Say("雪莲姥姥：你走，你走！拿着雪莲马上给我走！", 75);
	Say("张琳心：姥姥——多谢姥姥！", 101);
	AddGoods("Goods215_雪莲王.ini");
	SetNpcScript("雪莲姥姥", "雪莲姥姥对话.txt");
	SetMapTrap(01,"trap01.txt");
	Assign($Event, 520);
	Memo("张琳心来到天山，见到雪莲姥姥，打败她以后，得到雪莲王。");
	Return;

traps.trap01.txt:
// 切换到map086天山

	If ($Event == 480) @Event480;

	FadeOut();
	SaveNpc();
	SaveObj();
	LoadMap("map086_天山.map");
	LoadNpc("map086.npc");
	SaveNpc("temp_map086.npc");  //有反复战斗
	LoadObj("map086.obj");
	SetPlayerPos(7, 14);
	SetPlayerDir(1);
	ShowSnow(1);
	FadeIn();
	Return;
	
@Event480:
	Return;

traps.trap02.txt:
// 与雪莲姥姥战斗

	If ($Event == 480) @Event480;
	Return;
	
@Event480:	
	PlayerGoto(14, 23);
	SetPlayerDir(5);
	Say("白发老妇：这里已经很久没有生人来过了……你是谁啊？", 75);
	Say("张琳心：前辈，晚辈前来求取天山的雪莲王……", 101);
	Say("白发老妇：什么前辈晚辈的！罗罗嗦嗦，我没问你来干什么！回答我的问题！", 75);
	Say("张琳心：晚辈张琳心，为求……", 101);
	Say("白发老妇：很好，现在我再问你……", 75);
	Say("张琳心：前辈，晚辈想……", 104);
	Say("白发老妇：听清楚了！第一个问题：你知道我是谁吗？", 75);
	
	Choose("张琳心：前辈是……", "A 雪莲姥姥", "B 天山童姥", $Choosewho);
	If ($Choosewho == 0) @Choose01;
	If ($Choosewho == 1) @Choose02;
@Choose01:
	Say("张琳心：前辈仙居在这雪窟之中，自然是守护雪莲王的雪莲姥姥。", 101);
	Say("雪莲姥姥：哈哈哈哈，娃娃居然知道姥姥的名字。很好，那姥姥就让你两成的功力。", 75);
	Say("张琳心：让我两成功力，难道……", 105);
	Assign($Xuelao, 1);
	Goto @Lable01;
@Choose02:	
	Say("张琳心：前辈莫非是书中所说的——天山童姥？", 101);
	Say("雪莲姥姥：胡说八道，什么童姥、童子……我乃是天山的雪莲姥姥。你想激怒我，姥姥不会轻易上当的！再回答我第二个问题！", 75);
	Goto @Lable01;

@Lable01:	
	Say("雪莲姥姥：第二个问题：女人最想要又最怕要的，是什么样的男人？是俊秀的男子，还是英雄一样的男人？", 75);
	Choose("张琳心：是……", "A 俊秀的男人", "B 英雄式的男人", $Chooseman);
	If ($Chooseman == 0) @Choose03;
	If ($Chooseman == 1) @Choose04;
@Choose03:	
	Say("张琳心：女人最想要又最怕要的是——俊秀的男子。", 101);
	Say("雪莲姥姥：哼！漂亮的臭皮囊天下多的是，凭什么让女人又爱又怕。错！大错特错！错！错！错！", 75);
	Goto @Lable02;
@Choose04:
	Say("张琳心：让我又爱又怕的男人……他，当然是一个英雄……当有一天，你要失去他的时候，才发现世间再没有值得留恋的东西。", 104);
	Say("雪莲姥姥：……这样的男人，女人永远留不住他的心；等到一天，他离你而去，也永远带走了你的心——", 75);
	Say("张琳心：……", 104);
	Say("雪莲姥姥：……很好，姥姥就让你两成功力。", 75);
	Add($Xuelao, 1);
	Goto @Lable02;
	
@Lable02:
	Say("雪莲姥姥：第三个问题：你从洞口到这里一共走了几步？", 75);
	Choose("张琳心：这……", "A 一步", "B 二十五步", $Choosedistance);
	If ($Choosedistance == 0) @Choose05;
	If ($Choosedistance == 1) @Choose06;
@Choose05:
	Say("张琳心：只一步！", 101);
	Say("雪莲姥姥：哈哈哈哈——不错，只一步：“从生到死，或是从死到生！”", 75);
	Say("雪莲姥姥：姥姥越看越喜欢你了。好，姥姥就再让你两成功力！", 75);
	Add($Xuelao, 1);
	Goto @Lable03;
@Choose06:
	Say("张琳心：晚辈大概走了二十五步。", 101);
	Say("雪莲姥姥：愚蠢！愚蠢啊！人生一世无非两步：从虚到有，从生到死，何来这许多琐碎！", 75);
	Say("张琳心：晚辈明白了！", 101);
	Goto @Lable03;
	
@Lable03:	
	Say("雪莲姥姥：最后一个问题：你可愿意留在这人间仙境，作姥姥的徒弟，享受这无忧无虑的神仙生活？", 75);
	Choose("张琳心：前辈，这……", "A 婉转谢绝", "B 坚决拒绝", $Choosestay);
	If ($Choosestay == 0) @Choose07;
	If ($Choosestay == 1) @Choose08;
@Choose07:
	Say("张琳心：多谢前辈的好意，不过琳儿要赶去救独孤哥哥，还请姥姥大发慈悲赐晚辈一棵雪莲。", 104);
	Say("雪莲姥姥：那你是不愿了。要雪莲不难，如果你能打赢我，姥姥自然会给你。", 75);
	Goto @End;
@Choose08:
	Say("张琳心：不行！独孤哥哥命在旦夕，我要取雪莲去救他……前辈的要求，晚辈万万不能答应！", 101);
	Say("雪莲姥姥：从来没有人能在姥姥面前说两个“不”字，你知道为什么吗？", 75);
	Say("张琳心：？……", 105);
	Say("雪莲姥姥：因为，那些敢说“不”的，已经没有机会说第二次了。你很好，居然在姥姥面前连说了两次……姥姥真是越来越喜欢你了，好，姥姥就再让你两成功力。", 75);
	Add($Xuelao, 1);
	Goto @End;

@End:
	Say("雪莲姥姥：问题已经问完了，如果你要得到雪莲，就得先过我这一关，娃娃，开始吧！", 75);
		
	If ($Xuelao == 0) @End0;
	If ($Xuelao == 1) @End1;
	If ($Xuelao == 2) @End2;
	If ($Xuelao == 3) @End3;
	If ($Xuelao == 4) @End4;	
	Return;
	
@End0:
	StopMusic();
	PlayMusic("沙场.mp3");
	SetNpcRelation("雪莲姥姥", 1);
    SetPlayerState(1);
    EnableFight();
	EnableNpcAI();
	SetMapTrap(2,"");
	Return;

@End1:	
	DelNpc("雪莲姥姥");
	AddNpc("npc047_雪莲姥姥减二成功力.ini", 16, 18, 1);		//雪莲姥姥功力减少两成
	SaveNpc();
	StopMusic();
	PlayMusic("沙场.mp3");
	SetNpcRelation("雪莲姥姥", 1);
    SetPlayerState(1);
    EnableFight();
	EnableNpcAI();
	SetMapTrap(2,"");
	Return;
	
@End2:	
	DelNpc("雪莲姥姥");
	AddNpc("npc047_雪莲姥姥减四成功力.ini", 16, 18, 1);		//雪莲姥姥功力减少四成
	StopMusic();
	PlayMusic("沙场.mp3");
	SetNpcRelation("雪莲姥姥", 1);
    SetPlayerState(1);
    EnableFight();
	EnableNpcAI();
	SetMapTrap(2,"");
	Return;
	
@End3:
	DelNpc("雪莲姥姥");
	AddNpc("npc047_雪莲姥姥减六成功力.ini", 16, 18, 1);		//雪莲姥姥功力减少六成
	StopMusic();
	PlayMusic("沙场.mp3");
	SetNpcRelation("雪莲姥姥", 1);
    SetPlayerState(1);
    EnableFight();
	EnableNpcAI();
	SetMapTrap(2,"");
	Return;
	
@End4:
	DelNpc("雪莲姥姥");
	AddNpc("npc047_雪莲姥姥减八成功力.ini", 16, 18, 1);		//雪莲姥姥功力减少八成
	StopMusic();
	PlayMusic("沙场.mp3");
	SetNpcRelation("雪莲姥姥", 1);
    SetPlayerState(1);
    EnableFight();
	EnableNpcAI();
	SetMapTrap(2,"");
	Return;
